#include <limits>
#include <iostream>

int main() {
    // Type-safe retrieval of limits
    double d_max = std::numeric_limits<double>::max();
    long long ll_min = std::numeric_limits<long long>::min();

    std::cout << "Max double exponent: " 
              << std::numeric_limits<double>::max_exponent << "\n";

    // Using properties in generic code
    if (std::numeric_limits<int>::is_signed) {
        std::cout << "int is signed.\n";
    }

    // C-style equivalent (less type-safe, requires different headers)
    // #include <climits>
    // int c_max = INT_MAX;
}
